class Widget {
public:
  // Overload 1: Regular constructor
  Widget(int i, bool b) { /* ... */ }

  // Overload 2: Initializer-list constructor
  Widget(std::initializer_list<long double> il) { /* ... */ }
};

Widget w1(10, true); // Calls regular constructor

Widget w2{10, true}; // Calls initializer-list constructor!
                     // 10 and true are converted to long double

Widget w3(10, 5.0);  // Error: no matching regular constructor

Widget w4{10, 5.0};  // Calls initializer-list constructor
                     // 10 and 5.0 are converted to long double
